// Key order is the same for every language. importHelp is kept short
// so it can be translated properly in all 77 languages.
const _keys = [
  'yourBooks', 'searchHint', 'importBook', 'noBooksYet', 'noBooksMatch',
  'importHelp', 'showAllBooks', 'language', 'chooseLanguage', 'all',
  'favourites', 'toRead', 'reading', 'finished', 'settings', 'dictionary',
  'support', 'continueReading', 'openingLibrary', 'openingBook',
  'books', 'find', 'goals',
];

Map<String, String> _m(List<String> v) {
  final m = <String, String>{};
  for (var i = 0; i < v.length && i < _keys.length; i++) {
    m[_keys[i]] = v[i];
  }
  return m;
}

